#include "web_assets.h"  // new page + fonts (generated by tools/web_embed.py from web/)

static WebServer server(80);

// ------------------------------------------------------------ helpers
// Every response (status line, headers and body) is written straight on the socket, non-blocking,
// in TCP-sized pieces. WiFiClient::write retries a stuck connection for 10 s per call and blocks the
// loop (touch UI, watchdog); here a connection without progress for 5 s is dropped and logged.
static String extraHeaders;  // set before sendBody(): "Name: value\r\n" lines

static bool sendRaw(int fd, const uint8_t* data, size_t len, size_t& sent, uint32_t& last) {
  size_t done = 0;
  while (done < len) {
    const size_t n = len - done < 1436 ? len - done : 1436;
    const int w = send(fd, data + done, n, MSG_DONTWAIT);
    if (w > 0) {
      done += (size_t)w;
      sent += (size_t)w;
      last = millis();
      feedLoopWDT();
      continue;
    }
    if (w < 0 && errno != EAGAIN && errno != EWOULDBLOCK) return false;  // closed / reset by the browser
    if (millis() - last > 5000) return false;
    delay(2);
  }
  return true;
}

static void sendBody(int code, const char* type, const uint8_t* data, size_t len, const char* what) {
  WiFiClient c = server.client();
  const int fd = c.fd();
  String head;
  head.reserve(160 + extraHeaders.length());
  head = "HTTP/1.1 ";
  head += code;
  head += code == 200 ? " OK" : code == 404 ? " Not Found" : code == 500 ? " Internal Server Error" : " Bad Request";
  head += "\r\nContent-Type: ";
  head += type;
  head += "\r\nContent-Length: ";
  head += (unsigned)len;
  head += "\r\nConnection: close\r\n";
  head += extraHeaders;
  head += "\r\n";
  extraHeaders = "";
  size_t sent = 0;
  uint32_t last = millis();
  const bool ok = fd >= 0 && sendRaw(fd, (const uint8_t*)head.c_str(), head.length(), sent, last) &&
                  sendRaw(fd, data, len, sent, last);
  if (!ok && fd >= 0 && millis() - last > 5000)
    Serial.printf("[web] %s: no progress for 5 s after %u of %u bytes - dropped (DRAM %u free, %u min, "
                  "%u largest)\n",
                  what, (unsigned)sent, (unsigned)(head.length() + len),
                  (unsigned)heap_caps_get_free_size(MALLOC_CAP_8BIT | MALLOC_CAP_INTERNAL),
                  (unsigned)heap_caps_get_minimum_free_size(MALLOC_CAP_8BIT | MALLOC_CAP_INTERNAL),
                  (unsigned)heap_caps_get_largest_free_block(MALLOC_CAP_8BIT | MALLOC_CAP_INTERNAL));
  if (!ok) c.stop();
}

static void sendText(int code, const char* type, const String& body) {
  sendBody(code, type, (const uint8_t*)body.c_str(), body.length(), server.uri().c_str());
}

static void sendJson(JsonDocument& d, int code = 200) {
  String out;
  serializeJson(d, out);
  sendText(code, "application/json", out);
}

static void sendError(const char* msg, int code = 400) {
  JsonDocument d;
  d["ok"] = false;
  d["err"] = msg;
  sendJson(d, code);
}

static bool parseBody(JsonDocument& d) {
  if (!server.hasArg("plain")) return false;
  return deserializeJson(d, server.arg("plain")) == DeserializationError::Ok;
}

// works on a document member (doc["x"]) too: a MemberProxy converted to a
// JsonVariant does not create the member, so assign through the proxy itself
// (by reference: ArduinoJson 7.4 proxies cannot be copied)
template <typename T>
static void setNum(T&& v, float x) {
  if (isnan(x)) v.set(nullptr);
  else v.set(roundf(x * 10.0f) / 10.0f);
}

// ------------------------------------------------------------ status / history
// "autotune" of a local channel (nothing while no autotune ran)
static void tuneJson(JsonObject o, int ch) {
  LocalTune t;
  localCtrlTuneGet(ch, t);
  if (t.state == TuneState::Idle) return;
  static const char* const TS[] = {"idle", "running", "done", "failed"};
  JsonObject a = o["autotune"].to<JsonObject>();
  a["state"] = TS[(int)t.state];
  setNum(a["sp"], t.sp);
  a["cycle"] = t.cycle;
  a["elapsed"] = (int)t.elapsed;
  a["msg"] = t.msg;
  if (t.state == TuneState::Done) {
    a["kp"] = t.res.kp;
    a["ki"] = t.res.ki;
    a["kd"] = t.res.kd;
    a["ku"] = t.res.ku;
    a["pu"] = t.res.pu;
  }
}

static void stageJson(JsonObject o, const StageInfo& si) {
  o["idx"] = si.idx;
  o["stage"] = stageName(si.st);
  o["el"] = roundf(si.el * 10) / 10;
  o["dur"] = roundf(si.dur * 10) / 10;
}

// "run" object of /api/status: the fields of the old page (bottom channel /
// Sequence phase) plus the Duo run state for both channels
static void runStatusJson(JsonObject r, const LiveData& L) {
  r["state"] = runStateName(L.state);
  r["phase"] = stageName(L.phase);  // legacy: ramp / hold / wait / ...
  r["step"] = L.step;
  r["phaseEl"] = L.phaseEl;
  r["phaseDur"] = L.phaseDur;
  r["elapsed"] = L.elapsed;
  r["total"] = L.total;
  r["remaining"] = L.remaining;
  r["soakWait"] = L.soakWait;
  setNum(r["hostSp"], L.hostSp);
  setNum(r["target"], L.target);
  r["spSynced"] = L.spSynced;
  r["spWrites"] = L.spWrites;
  r["msg"] = L.runMsg;
  r["prog"] = L.runProg;
  r["name"] = L.runName;
  r["steps"] = L.stepCount;
  if (L.runProg < 0) return;
  r["type"] = progTypeName(L.progType);
  r["waiting"] = L.waiting;
  r["progPause"] = L.progPause;
  r["actionRequired"] = L.pauseMsg;
  r["pauseText"] = L.pauseText;
  r["edited"] = L.runEdited;
  if (L.progType == PROG_SEQ) {
    stageJson(r["seq"].to<JsonObject>(), L.seq);
    r["phases"] = L.phases;
  }
  JsonArray a = r["channels"].to<JsonArray>();
  for (int i = 0; i < NUM_CHANNELS; ++i) {
    const ChOut& o = L.run[i];
    JsonObject c = a.add<JsonObject>();
    c["inProgram"] = o.inProgram;
    c["idle"] = o.idle;
    setNum(c["sp"], o.sp);
    setNum(c["target"], o.target);
    c["moving"] = o.moving;
    c["synced"] = L.spSyncedCh[i];
    c["spWrites"] = L.spWritesCh[i];
    if (L.progType == PROG_TL) {
      stageJson(c["lane"].to<JsonObject>(), L.lane[i]);
      c["steps"] = L.steps[i];
    }
  }
}

static void handleStatus() {
  LiveData L;
  Settings S;
  {
    Guard g;
    L = gLive;
    S = gSettings;
  }
  JsonDocument d;
  JsonObject c = d["comm"].to<JsonObject>();
  c["ok"] = L.commOk;
  c["okCount"] = L.okCount;
  c["errCount"] = L.errCount;
  c["err"] = L.lastErr;
  setNum(d["pv"], L.pvValid ? L.pv : NAN);
  d["pvFlag"] = Controller::flagName(L.pvFlag);
  setNum(d["spEff"], L.spEffValid ? L.spEff : NAN);
  setNum(d["out"], L.outValid ? L.out : NAN);
  if (L.statusValid) {
    d["status"] = L.status;
    if (S.ch[ENGINE_CH].mb.profile == PROFILE_PMA_KS4X) d["mode"] = pmaModeText(L.status);
  }
  if (L.alarmValid) d["alarm"] = L.alarm;
  JsonObject r = d["run"].to<JsonObject>();
  runStatusJson(r, L);
  JsonObject m = d["manual"].to<JsonObject>();
  m["on"] = L.manualOn;
  setNum(m["sp"], S.ch[ENGINE_CH].manualSp);
  m["synced"] = L.manualSynced;
  d["sel"] = S.selProgram;
  {
    ProgSummary ps;
    const bool used = programSummary(S.selProgram, ps);
    d["selName"] = used ? ps.name : "";
    d["selSteps"] = used ? ps.items : 0;
    d["plannedTotal"] = used ? ps.total : 0;
  }
  d["spConfigured"] = S.ch[ENGINE_CH].mb.reg.sp != REG_UNSET;
  d["profile"] = S.ch[ENGINE_CH].mb.profile;
  d["net"] = netInfo();
  d["uptime"] = millis() / 1000;
  d["fw"] = FW_VERSION;
  d["board"] = BOARD_NAME;
  d["variant"] = BOARD_VARIANT;
  // both channels (the fields above are the bottom channel, for the old page)
  JsonArray chs = d["channels"].to<JsonArray>();
  for (int i = 0; i < NUM_CHANNELS; ++i) {
    const ChannelLive& C = L.ch[i];
    JsonObject o = chs.add<JsonObject>();
    o["name"] = C.name;
    o["type"] = channelTypeName(C.type);
    o["ok"] = C.commOk;
    o["err"] = C.lastErr;
    setNum(o["pv"], C.pvValid ? C.pv : NAN);
    o["pvFlag"] = Controller::flagName(C.pvFlag);
    setNum(o["sp"], C.spEffValid ? C.spEff : NAN);
    setNum(o["out"], C.outValid ? C.out : NAN);
    if (C.statusValid && C.type == CH_MODBUS && S.ch[i].mb.profile == PROFILE_PMA_KS4X) o["mode"] = pmaModeText(C.status);
    if (C.type == CH_LOCAL) {
      setNum(o["cold"], C.coldC);
      tuneJson(o, i);
    }
    o["fault"] = C.fault ? C.faultText : "";
    JsonObject m = o["manual"].to<JsonObject>();
    m["on"] = C.manualOn;
    setNum(m["sp"], S.ch[i].manualSp);
    m["synced"] = C.manualSynced;
  }
  sendJson(d);
}

// Log of the last program run (if there was one since boot), else the live window. Both channels.
static void handleCsv() {
  String out = "time_s,bottom_pv,bottom_sp,bottom_plan,top_pv,top_sp,top_plan\n";
  out.reserve(CHART_N * 48 + 80);
  char line[112];
  bool run;
  auto num = [](char* b, size_t n, float v) {
    if (isnan(v)) b[0] = 0;
    else snprintf(b, n, "%.1f", v);
  };
  {
    Guard g;  // build the text under the lock, send it afterwards
    run = gHist->runValid;
    for (int i = 0; i < CHART_N; ++i) {
      float v[6];
      for (int c = 0; c < NUM_CHANNELS; ++c) {
        v[c * 3] = run ? gHist->runPv[c][i] : gHist->livePv[c][i];
        v[c * 3 + 1] = run ? gHist->runSp[c][i] : gHist->liveSp[c][i];
        v[c * 3 + 2] = run ? gHist->runPlan[c][i] : NAN;
      }
      if (isnan(v[0]) && isnan(v[1]) && isnan(v[3]) && isnan(v[4])) continue;
      const float t = run ? i * gHist->runBin : -(float)(CHART_N - 1 - i) * LIVE_SAMPLE_SEC;
      char f[6][12];
      for (int k = 0; k < 6; ++k) num(f[k], sizeof(f[k]), v[k]);
      snprintf(line, sizeof(line), "%.0f,%s,%s,%s,%s,%s,%s\n", t, f[0], f[1], f[2], f[3], f[4], f[5]);
      out += line;
    }
  }
  extraHeaders = String("Content-Disposition: ") + (run ? "attachment; filename=tempctl-duo-run.csv"
                                               : "attachment; filename=tempctl-duo-live.csv") + "\r\n";
  sendText(200, "text/csv", out);
}

// ------------------------------------------------------------ program / commands
static void handleGetPrograms() {
  static ProgSummary list[PROG_MAX];
  programSummaries(list);
  JsonDocument d;
  {
    Guard g;
    d["sel"] = gSettings.selProgram;
    d["spMin"] = gSettings.ch[ENGINE_CH].spMin;
    d["spMax"] = gSettings.ch[ENGINE_CH].spMax;
  }
  d["max"] = PROG_MAX;
  d["maxPhases"] = PROG_MAX_PHASES;
  d["maxSteps"] = PROG_MAX_STEPS;
  JsonArray a = d["programs"].to<JsonArray>();
  for (int i = 0; i < PROG_MAX; ++i) {
    const ProgSummary& p = list[i];
    JsonObject o = a.add<JsonObject>();
    o["used"] = p.used != 0;
    if (!p.used) {
      char n[16];
      snprintf(n, sizeof(n), "Program %d", i + 1);
      o["name"] = n;
      o["steps"] = 0;
      o["total"] = 0;
      continue;
    }
    o["name"] = p.name;
    o["type"] = progTypeName(p.type);
    o["steps"] = p.items;  // phases (Sequence) / steps of both channels (Timeline)
    o["total"] = p.total;
    o["waits"] = p.waits != 0;
    JsonArray u = o["uses"].to<JsonArray>();
    u.add((p.uses & 1) != 0);
    u.add((p.uses & 2) != 0);
  }
  sendJson(d);
}

static int progIndexArg(JsonVariantConst v) {
  if (!v.isNull()) return v.as<int>();
  if (server.hasArg("i")) return server.arg("i").toInt();
  Guard g;
  return gSettings.selProgram;
}

// {"i":0,"used":true,"program":{Duo program JSON}}
static void sendProgram(int i) {
  ScratchProg sp;
  if (!sp) return sendError("Out of memory", 500);
  DuoProgram& p = *sp;
  char err[96];
  const bool used = programLoad(i, p, err, sizeof(err));
  JsonDocument d;
  d["i"] = i;
  d["used"] = used;
  if (used) progToJson(p, d["program"].to<JsonObject>());
  sendJson(d);
}

static void handleGetProgram() {
  const int i = progIndexArg(JsonVariantConst());
  if (i < 0 || i >= PROG_MAX) return sendError("Program index out of range");
  sendProgram(i);
}

// Body: {"i":0,"program":{"fmt":1,"name":"...","type":"seq","phases":[...]}}  (spec 9.3.5)
//       {"i":0,"delete":true}
static void handlePostProgram() {
  JsonDocument d;
  if (!parseBody(d)) return sendError("Invalid JSON");
  const int i = progIndexArg(d["i"]);
  if (i < 0 || i >= PROG_MAX) return sendError("Program index out of range");
  if (d["delete"] | false) {
    if (!programDelete(i)) return sendError("Deleting the program failed", 500);
    return sendProgram(i);
  }
  if (!d["program"].is<JsonObjectConst>()) return sendError("program missing");
  ScratchProg sp;
  if (!sp) return sendError("Out of memory", 500);
  DuoProgram& p = *sp;
  char err[128];
  const char* names[NUM_CHANNELS];
  float lo[NUM_CHANNELS], hi[NUM_CHANNELS];
  static char nameBuf[NUM_CHANNELS][CH_NAME_LEN];
  {
    Guard g;
    for (int c = 0; c < NUM_CHANNELS; ++c) {
      strlcpy(nameBuf[c], gSettings.ch[c].name, sizeof(nameBuf[c]));
      names[c] = nameBuf[c];
      lo[c] = gSettings.ch[c].spMin;
      hi[c] = gSettings.ch[c].spMax;
    }
  }
  if (!progFromJson(d["program"].as<JsonObjectConst>(), p, err, sizeof(err), names)) return sendError(err);
  if (!progCheckLimits(p, lo, hi, err, sizeof(err), names)) return sendError(err);
  if (!programSave(i, p, err, sizeof(err))) return sendError(err, 500);
  sendProgram(i);
}

static void handleSelect() {
  JsonDocument d;
  if (!parseBody(d)) return sendError("Invalid JSON");
  const int i = d["i"] | -1;
  if (i < 0 || i >= PROG_MAX) return sendError("Program index out of range");
  selectProgram(i);
  JsonDocument r;
  r["ok"] = true;
  r["sel"] = i;
  sendJson(r);
}

// GET: the running (or last) program's running copy, with its run edits
static void handleGetRun() {
  JsonDocument d;
  LiveData L;
  {
    Guard g;
    L = gLive;
  }
  runStatusJson(d["run"].to<JsonObject>(), L);
  if (!runProgramJson(d["program"].to<JsonObject>())) d.remove("program");
  sendJson(d);
}

// Run control and run edits (spec 9.3.4); results in /api/status run.msg
//   {"cmd":"extend","ch":0,"sec":30}           current hold +30 s (Sequence: ch ignored)
//   {"cmd":"hold","ch":1,"idx":4,"sec":45}      hold time of phase / step idx (-1 = current)
//   {"cmd":"ramp","ch":1,"idx":5,"sec":40}      later ramps only
//   {"cmd":"target","ch":0,"idx":-1,"t":170}    current / kept target (or a later one)
//   {"cmd":"save"}                              store the run edits into the program
//   {"cmd":"next"} / {"cmd":"continue"}
//   {"cmd":"start","i":0,"program":{...}}      start slot 0 with this (unsaved) content
static void handlePostRun() {
  JsonDocument d;
  if (!parseBody(d)) return sendError("Invalid JSON");
  const char* c = d["cmd"] | "";
  const int ch = d["ch"] | 0;
  const int idx = d["idx"] | -1;
  bool ok;
  if (!strcmp(c, "extend")) ok = sendCmd(CMD_RUN_EDIT, ch, d["sec"] | 0.0f, -1, EDIT_EXTEND);
  else if (!strcmp(c, "hold")) ok = sendCmd(CMD_RUN_EDIT, ch, d["sec"] | 0.0f, idx, EDIT_HOLD);
  else if (!strcmp(c, "ramp")) ok = sendCmd(CMD_RUN_EDIT, ch, d["sec"] | 0.0f, idx, EDIT_RAMP);
  else if (!strcmp(c, "target")) {
    if (!d["t"].is<float>()) return sendError("t (target) missing");
    ok = sendCmd(CMD_RUN_EDIT, ch, d["t"].as<float>(), idx, EDIT_TARGET);
  } else if (!strcmp(c, "save")) ok = sendCmd(CMD_SAVE_RUN);
  else if (!strcmp(c, "start")) {  // "Start without saving": {"cmd":"start","i":n,"program":{...}}
    const int i = d["i"] | -1;
    if (i < 0 || i >= PROG_MAX) return sendError("Program index out of range");
    ScratchProg sp;
    if (!sp) return sendError("Out of memory", 500);
    DuoProgram& p = *sp;
    char err[128];
    const char* names[NUM_CHANNELS];
    float lo[NUM_CHANNELS], hi[NUM_CHANNELS];
    static char nameBuf[NUM_CHANNELS][CH_NAME_LEN];
    {
      Guard g;
      for (int c = 0; c < NUM_CHANNELS; ++c) {
        strlcpy(nameBuf[c], gSettings.ch[c].name, sizeof(nameBuf[c]));
        names[c] = nameBuf[c];
        lo[c] = gSettings.ch[c].spMin;
        hi[c] = gSettings.ch[c].spMax;
      }
    }
    if (!progFromJson(d["program"].as<JsonObjectConst>(), p, err, sizeof(err), names)) return sendError(err);
    if (!progCheckLimits(p, lo, hi, err, sizeof(err), names)) return sendError(err);
    ok = startDraft(i, p);
  }
  else if (!strcmp(c, "next")) ok = sendCmd(CMD_NEXT);
  else if (!strcmp(c, "continue")) ok = sendCmd(CMD_CONTINUE);
  else return sendError("cmd must be extend, hold, ramp, target, save, start, next or continue");
  JsonDocument r;
  r["ok"] = ok;
  sendJson(r);
}

// Body: {"sp":150.0} and/or {"on":true|false}
static void handleManual() {
  JsonDocument d;
  if (!parseBody(d)) return sendError("Invalid JSON");
  const int ch = d["ch"] | (int)ENGINE_CH;  // 0 = bottom (default), 1 = top
  if (ch < 0 || ch >= NUM_CHANNELS) return sendError("ch must be 0 (bottom) or 1 (top)");
  if (!d["sp"].isNull()) setManualSp(d["sp"].as<float>(), ch);
  bool ok = true;
  if (!d["on"].isNull()) ok = sendCmd(d["on"].as<bool>() ? CMD_MANUAL_ON : CMD_MANUAL_OFF, ch);
  JsonDocument r;
  r["ok"] = ok;
  sendJson(r);
}

// {"ch":0}: acknowledge a channel's latched fault (runaway, sensor, over temperature)
static void handleAck() {
  JsonDocument d;
  if (!parseBody(d)) return sendError("Invalid JSON");
  const int ch = d["ch"] | -1;
  if (ch < 0 || ch >= NUM_CHANNELS) return sendError("ch must be 0 (bottom) or 1 (top)");
  JsonDocument r;
  r["ok"] = sendCmd(CMD_ACK_FAULT, ch);
  sendJson(r);
}

// PID autotune of a local channel:
//   {"ch":1,"cmd":"start","sp":200}  relay test around 200 degC
//   {"ch":1,"cmd":"stop"}
//   {"ch":1,"cmd":"accept"}          take the proposed kp/ki/kd into the settings
//   {"ch":1,"cmd":"discard"}
static void handleAutotune() {
  JsonDocument d;
  if (!parseBody(d)) return sendError("Invalid JSON");
  const int ch = d["ch"] | -1;
  if (ch < 0 || ch >= NUM_CHANNELS) return sendError("ch must be 0 (bottom) or 1 (top)");
  const char* cmd = d["cmd"] | "";
  JsonDocument r;
  if (!strcmp(cmd, "start")) {
    const float sp = d["sp"] | NAN;
    if (isnan(sp)) return sendError("sp (test temperature) missing");
    r["ok"] = sendCmd(CMD_TUNE_START, ch, sp);
  } else if (!strcmp(cmd, "stop")) {
    r["ok"] = sendCmd(CMD_TUNE_STOP, ch);
  } else if (!strcmp(cmd, "accept") || !strcmp(cmd, "discard")) {
    LocalTune t;
    localCtrlTuneGet(ch, t);
    if (t.state == TuneState::Running) return sendError("autotune is still running");
    if (!strcmp(cmd, "accept")) {
      if (t.state != TuneState::Done) return sendError("no autotune result to accept");
      {
        Guard g;
        LocalChannelSettings& l = gSettings.ch[ch].loc;
        l.kp = t.res.kp;
        l.ki = t.res.ki;
        l.kd = t.res.kd;
      }
      saveSettingsAndNotify();
      r["kp"] = t.res.kp;
      r["ki"] = t.res.ki;
      r["kd"] = t.res.kd;
    }
    localCtrlTuneClear(ch);
    r["ok"] = true;
  } else {
    return sendError("cmd must be start, stop, accept or discard");
  }
  sendJson(r);
}

static void handleCmd() {
  JsonDocument d;
  if (!parseBody(d)) return sendError("Invalid JSON");
  const String c = d["cmd"] | "";
  CmdType t;
  int arg = d["prog"] | -1;
  if (c == "start") t = CMD_START;
  else if (c == "pause") t = CMD_PAUSE;
  else if (c == "resume") t = CMD_RESUME;
  else if (c == "stop") t = CMD_STOP;
  else if (c == "skip" || c == "next") t = CMD_NEXT;  // "skip": old page
  else if (c == "continue") t = CMD_CONTINUE;
  else return sendError("Unknown command");
  JsonDocument r;
  r["ok"] = sendCmd(t, arg);
  sendJson(r);
}

// ------------------------------------------------------------ settings document (Duo)
// GET: the whole settings JSON (/duo/settings.json without passwords).
// POST: a partial document; only the keys given are changed, e.g.
//   {"channels":[null,{"type":"modbus","modbus":{"addr":2}}]}
static void handleGetConfig() {
  static Settings S;  // static: large; web handlers run in the loop task only
  {
    Guard g;
    S = gSettings;
  }
  JsonDocument d;
  settingsToJson(S, d.to<JsonObject>(), true);
  // what this board variant can wire (not part of the settings; ignored when posted back)
  const BoardLimits lim = boardLimits();
  JsonObject l = d["limits"].to<JsonObject>();
  l["rs485"] = lim.rs485;
  l["localMax"] = lim.localMax;
  sendJson(d);
}

static void handlePostConfig() {
  JsonDocument d;
  if (!parseBody(d)) return sendError("Invalid JSON");
  static Settings S;
  char msg[200];
  {
    Guard g;
    S = gSettings;
  }
  if (!settingsFromJson(d.as<JsonObjectConst>(), S, msg, sizeof(msg))) return sendError(msg);
  // {"channels":[{"modbus":{"loadDefaults":true}}]}: register map of the (new) profile
  JsonArrayConst chs = d["channels"];
  for (int i = 0; i < NUM_CHANNELS && i < (int)chs.size(); ++i)
    if (chs[i]["modbus"]["loadDefaults"] | false) regMapDefaults(S.ch[i].mb.reg, S.ch[i].mb.profile);
  if (!settingsValidate(S, boardLimits(), msg, sizeof(msg))) return sendError(msg);
  {
    Guard g;
    gSettings = S;
  }
  saveSettingsAndNotify();
  handleGetConfig();
}

static void handleWifi() {
  JsonDocument d;
  if (!parseBody(d)) return sendError("Invalid JSON");
  {
    Guard g;
    if (d["ssid"].is<const char*>()) strlcpy(gSettings.ssid, d["ssid"], sizeof(gSettings.ssid));
    if (d["pass"].is<const char*>()) strlcpy(gSettings.pass, d["pass"], sizeof(gSettings.pass));
    if (d["apPass"].is<const char*>()) {
      const char* ap = d["apPass"];
      if (strlen(ap) >= 8) strlcpy(gSettings.apPass, ap, sizeof(gSettings.apPass));
    }
  }
  saveSettingsQuiet();
  JsonDocument r;
  r["ok"] = true;
  r["msg"] = "Saved. Connecting... If the address changes, reopen the page at the new IP or http://<host name>.local";
  sendJson(r);
  delay(300);  // let the response go out before the station reconnects
  netApplyWifi();
}

// GET /api/wifiscan?start=1 starts a scan; without start: {"busy":true} while scanning, then
// {"networks":[...]} (strongest first; kept until the next scan)
static void handleWifiScan() {
  static String last;     // names of the last scan, '\n'-separated
  static bool have = false;
  if (server.hasArg("start") && !netScanBusy()) {
    netScanStart();
    have = false;
  }
  JsonDocument d;
  if (netScanBusy()) {
    static char buf[1200];
    const int n = netScanResult(buf, sizeof(buf));
    if (n == -1) {
      d["busy"] = true;
      return sendJson(d);
    }
    last = n >= 0 ? String(buf) : String();
    have = n >= 0;
    if (n < 0) d["err"] = "Scan failed";
  }
  JsonArray a = d["networks"].to<JsonArray>();
  if (have) {
    int from = 0;
    while (from < (int)last.length()) {
      int e = last.indexOf('\n', from);
      if (e < 0) e = last.length();
      if (e > from) a.add(last.substring(from, e));
      from = e + 1;
    }
  }
  sendJson(d);
}

// POST /api/brightness {"v":128}: touch screen brightness while the web slider is dragged
// (applied by the UI loop, not saved; the slider saves through /api/config when released)
static void handleBrightness() {
  JsonDocument d;
  if (!parseBody(d)) return sendError("Invalid JSON");
  int v = d["v"] | -1;
  if (v < 0) return sendError("v missing");
  if (v < 10) v = 10;
  if (v > 255) v = 255;
  {
    Guard g;
    gSettings.brightness = (uint8_t)v;
  }
  JsonDocument r;
  r["ok"] = true;
  sendJson(r);
}

// POST /api/restart (refused while a program runs)
static uint32_t restartAt = 0;
static void handleRestart() {
  bool active;
  {
    Guard g;
    active = gLive.state == RunState::Running || gLive.state == RunState::Paused;
  }
  if (active) return sendError("A program is running - stop it first");
  logEvent("Restart requested from the web page");
  JsonDocument r;
  r["ok"] = true;
  sendJson(r);
  restartAt = millis() + 600;  // let the answer go out first
  if (!restartAt) restartAt = 1;
}

// ------------------------------------------------------------ bus tools
// Optional "ch" (query or JSON body): channel whose controller is used, 0 = bottom (default), 1 = top
static uint8_t argCh() {
  const long c = server.hasArg("ch") ? server.arg("ch").toInt() : 0;
  return (c >= 0 && c < NUM_CHANNELS) ? (uint8_t)c : 0;
}
static uint8_t bodyCh(const JsonDocument& b) {
  const int c = b["ch"] | 0;
  return (c >= 0 && c < NUM_CHANNELS) ? (uint8_t)c : 0;
}

static void handleMbRead() {
  BusRequest r{};
  r.ch = argCh();
  r.op = BUS_READ;
  r.addr = server.arg("addr").toInt();
  r.count = server.hasArg("n") ? server.arg("n").toInt() : 1;
  r.fn = server.hasArg("fn") ? server.arg("fn").toInt() : 0;
  if (r.fn != 0 && r.fn != 3 && r.fn != 4) r.fn = 0;
  const bool ok = busRequest(r);
  JsonDocument d;
  d["ok"] = ok;
  if (!ok) d["err"] = r.err;
  JsonArray a = d["values"].to<JsonArray>();
  for (int i = 0; i < r.n; ++i) a.add(r.values[i]);
  sendJson(d);
}

static void handleMbWrite() {
  JsonDocument b;
  if (!parseBody(b)) return sendError("Invalid JSON");
  BusRequest r{};
  r.ch = bodyCh(b);
  r.op = BUS_WRITE;
  r.addr = b["addr"] | 0;
  r.value = b["value"] | 0;
  const bool ok = busRequest(r);
  JsonDocument d;
  d["ok"] = ok;
  if (!ok) d["err"] = r.err;
  sendJson(d);
}

static void handleFindSp() {
  JsonDocument b;
  parseBody(b);
  BusRequest r{};
  r.ch = bodyCh(b);
  r.op = BUS_FINDSP;
  {
    Guard g;
    r.from = b["from"] | gSettings.scanFrom;
    r.to = b["to"] | gSettings.scanTo;
  }
  const bool ok = busRequest(r, 60000);
  JsonDocument d;
  d["ok"] = ok;
  if (!ok) d["err"] = r.err;
  d["reference"] = r.refValue;
  JsonArray a = d["candidates"].to<JsonArray>();
  for (int i = 0; i < r.n; ++i) a.add((uint16_t)r.values[i]);
  sendJson(d);
}

// ------------------------------------------------------------ controller parameters
static void handleGetParams() {
  uint8_t profile;
  float scale;
  const uint8_t ch = argCh();
  {
    Guard g;
    profile = gSettings.ch[ch].mb.profile;
    scale = gSettings.ch[ch].mb.reg.scale;
  }
  JsonDocument d;
  d["supported"] = profile == PROFILE_PMA_KS4X;
  JsonArray pa = d["params"].to<JsonArray>();
  JsonArray aa = d["actions"].to<JsonArray>();
  if (profile == PROFILE_PMA_KS4X) {
    int n;
    const ParamDef* p = pmaParams(n);
    for (int i = 0; i < n; ++i) {
      JsonObject o = pa.add<JsonObject>();
      o["name"] = p[i].name;
      o["addr"] = p[i].addr;
      o["scaled"] = p[i].scaled != 0;
      o["desc"] = p[i].desc;
      BusRequest r{};
      r.ch = ch;
      r.op = BUS_READ;
      r.addr = p[i].addr;
      r.count = 1;
      if (busRequest(r, 3000)) {
        const int16_t raw = r.values[0];
        if (Controller::classify(raw) == VAL_OFF) o["value"] = "off";
        else if (p[i].scaled) o["value"] = raw / scale;
        else o["value"] = raw;
      } else {
        o["err"] = r.err;
      }
    }
    const ActionDef* a = pmaActions(n);
    for (int i = 0; i < n; ++i) aa.add(a[i].label);
  }
  sendJson(d);
}

static void handlePostParam() {
  JsonDocument b;
  if (!parseBody(b)) return sendError("Invalid JSON");
  float scale;
  const uint8_t ch = bodyCh(b);
  {
    Guard g;
    scale = gSettings.ch[ch].mb.reg.scale;
  }
  BusRequest r{};
  r.ch = ch;
  r.op = BUS_WRITE;
  r.addr = b["addr"] | 0;
  const bool scaled = b["scaled"] | false;
  const String v = b["value"].is<const char*>() ? String((const char*)b["value"]) : String(b["value"].as<float>());
  if (v == "off") r.value = -32000;
  else r.value = (int16_t)lroundf(v.toFloat() * (scaled ? scale : 1.0f));
  // only allow addresses from the parameter table
  int n;
  const ParamDef* p = pmaParams(n);
  bool allowed = false;
  for (int i = 0; i < n; ++i) allowed |= p[i].addr == r.addr && strcmp(p[i].name, "Sw.Op") != 0;
  if (!allowed) return sendError("Address is not an editable parameter");
  const bool ok = busRequest(r);
  JsonDocument d;
  d["ok"] = ok;
  if (!ok) d["err"] = r.err;
  sendJson(d);
}

static void handleAction() {
  JsonDocument b;
  if (!parseBody(b)) return sendError("Invalid JSON");
  int n;
  const ActionDef* a = pmaActions(n);
  const int i = b["i"] | -1;
  if (i < 0 || i >= n) return sendError("Unknown action");
  BusRequest r{};
  r.ch = bodyCh(b);
  r.op = BUS_WRITE;
  r.addr = a[i].addr;
  r.value = a[i].value;
  const bool ok = busRequest(r);
  JsonDocument d;
  d["ok"] = ok;
  if (!ok) d["err"] = r.err;
  sendJson(d);
}

// ------------------------------------------------------------ new page (step 7)

static void sendAsset(const WebAsset& a) {
  extraHeaders = a.gzip ? "Content-Encoding: gzip\r\n" : "";
  extraHeaders += a.immutable ? "Cache-Control: public, max-age=31536000, immutable\r\n" : "Cache-Control: no-cache\r\n";
  sendBody(200, a.type, a.data, a.len, a.path);
}

static const char* const CH_KEYS[NUM_CHANNELS] = {"b", "t"};

// Everything the Status page polls (1 s): both channels, run state, counters
static void handleLive() {
  static LiveData L;  // web task only
  static Settings S;
  {
    Guard g;
    L = gLive;
    S = gSettings;
  }
  JsonDocument d;
  d["up"] = millis() / 1000;
  d["fw"] = FW_VERSION;
  d["board"] = BOARD_NAME;
  d["variant"] = BOARD_VARIANT;
  d["net"] = netInfo();
  d["sel"] = S.selProgram;
  d["progGen"] = programStoreGen();
  d["logSeq"] = logSeq();
  d["cfgGen"] = settingsGen();
  char hex[8];
  snprintf(hex, sizeof(hex), "#%06X", (unsigned)(S.accentColor & 0xFFFFFF));
  d["accent"] = hex;
  d["band"] = S.bottomBand;
  d["pollMs"] = S.pollMs;  // the page polls this fast (250..1000 ms)
  JsonObject r = d["run"].to<JsonObject>();
  r["state"] = runStateName(L.state);
  r["prog"] = L.runProg;
  if (L.runProg >= 0) {
    r["name"] = L.runName;
    r["type"] = progTypeName(L.progType);
    r["el"] = roundf(L.elapsed * 10) / 10;
    r["rem"] = roundf(L.remaining * 10) / 10;
    r["progPause"] = L.progPause;
    r["actionRequired"] = L.pauseMsg;
    r["pauseText"] = L.pauseText;
    r["edited"] = L.runEdited;
    r["waiting"] = L.waiting;
    if (L.progType == PROG_SEQ) {
      stageJson(r["seq"].to<JsonObject>(), L.seq);
      r["phases"] = L.phases;
    }
  }
  r["msg"] = L.runMsg;
  JsonArray a = d["ch"].to<JsonArray>();
  for (int i = 0; i < NUM_CHANNELS; ++i) {
    const ChannelLive& C = L.ch[i];
    const ChannelSettings& cs = S.ch[i];
    const ChOut& o = L.run[i];
    JsonObject c = a.add<JsonObject>();
    c["key"] = CH_KEYS[i];
    c["name"] = C.name;
    c["type"] = channelTypeName(C.type);
    c["ok"] = C.commOk;
    c["err"] = C.lastErr;
    setNum(c["pv"], C.pvValid ? C.pv : NAN);
    c["pvFlag"] = Controller::flagName(C.pvFlag);
    setNum(c["sp"], C.spEffValid ? C.spEff : NAN);
    setNum(c["out"], C.outValid ? C.out : NAN);
    if (C.statusValid && C.type == CH_MODBUS && cs.mb.profile == PROFILE_PMA_KS4X) c["mode"] = pmaModeText(C.status);
    if (C.type == CH_LOCAL) setNum(c["cold"], C.coldC);
    c["fault"] = C.fault ? C.faultText : "";
    c["spMin"] = cs.spMin;
    c["spMax"] = cs.spMax;
    c["inProgram"] = o.inProgram;
    c["state"] = chStateName((ChState)L.chSt[i]);
    c["idle"] = o.idle;
    setNum(c["runSp"], o.sp);
    setNum(c["target"], o.target);
    c["moving"] = o.moving;
    c["kept"] = L.kept[i];
    c["canExtend"] = L.canExt[i];
    c["synced"] = L.spSyncedCh[i];
    if (L.progType == PROG_TL && L.runProg >= 0) {
      stageJson(c["lane"].to<JsonObject>(), L.lane[i]);
      c["steps"] = L.steps[i];
    }
    JsonObject m = c["manual"].to<JsonObject>();
    m["on"] = C.manualOn;
    setNum(m["sp"], cs.manualSp);
    m["synced"] = C.manualSynced;
    if (C.type == CH_LOCAL) tuneJson(c, i);
  }
  sendJson(d);
}

// ?v=run: current / last run (history, lanes, events, forecast); ?v=live: rolling window
static void handleChart() {
  String out;
  chartJson(out, server.arg("v") != "live");
  extraHeaders = "Cache-Control: no-store\r\n";
  sendText(200, "application/json", out);
}

// ?since=n: event log entries after n
static void handleLog() {
  LogEntry* e = (LogEntry*)malloc(sizeof(LogEntry) * LOG_N);  // 5 kB, only while answering
  if (!e) return sendError("Out of memory", 500);
  const uint32_t since = server.hasArg("since") ? (uint32_t)server.arg("since").toInt() : 0;
  const int n = logSince(since, e, LOG_N);
  JsonDocument d;
  d["seq"] = logSeq();
  d["up"] = millis() / 1000;
  JsonArray a = d["log"].to<JsonArray>();
  for (int i = 0; i < n; ++i) {
    JsonArray x = a.add<JsonArray>();
    x.add(e[i].seq);
    x.add(e[i].upSec);
    if (isnan(e[i].runT)) x.add(nullptr);
    else x.add((int)e[i].runT);
    x.add(e[i].msg);
  }
  free(e);
  sendJson(d);
}

// ------------------------------------------------------------ setup
void webBegin() {
#ifdef BOARD_HAS_PSRAM
  server.on("/", HTTP_GET, [] { sendAsset(WEB_ASSETS[0]); });
#endif
  for (size_t i = 1; i < WEB_ASSET_COUNT; ++i) {
    const WebAsset* a = &WEB_ASSETS[i];
#ifdef BOARD_HAS_PSRAM
    if (!strcmp(a->path, "/nofonts")) continue;
#else
    // no PSRAM (CYD): the page without web fonts, no font downloads (system fonts instead)
    if (!strcmp(a->path, "/nofonts")) {
      server.on("/", HTTP_GET, [a] { sendAsset(*a); });
      continue;
    }
    if (!strncmp(a->path, "/f/", 3) && strcmp(a->path, "/f/OFL.txt")) continue;
#endif
    server.on(a->path, HTTP_GET, [a] { sendAsset(*a); });
  }
  server.on("/api/live", HTTP_GET, handleLive);
  server.on("/api/chart", HTTP_GET, handleChart);
  server.on("/api/log", HTTP_GET, handleLog);
  server.on("/api/status", HTTP_GET, handleStatus);
  server.on("/api/log.csv", HTTP_GET, handleCsv);
  server.on("/api/programs", HTTP_GET, handleGetPrograms);
  server.on("/api/program", HTTP_GET, handleGetProgram);
  server.on("/api/program", HTTP_POST, handlePostProgram);
  server.on("/api/select", HTTP_POST, handleSelect);
  server.on("/api/run", HTTP_GET, handleGetRun);
  server.on("/api/run", HTTP_POST, handlePostRun);
  server.on("/api/manual", HTTP_POST, handleManual);
  server.on("/api/cmd", HTTP_POST, handleCmd);
  server.on("/api/ack", HTTP_POST, handleAck);
  server.on("/api/autotune", HTTP_POST, handleAutotune);
  server.on("/api/wifi", HTTP_POST, handleWifi);
  server.on("/api/wifiscan", HTTP_GET, handleWifiScan);
  server.on("/api/restart", HTTP_POST, handleRestart);
  server.on("/api/brightness", HTTP_POST, handleBrightness);
  server.on("/api/config", HTTP_GET, handleGetConfig);
  server.on("/api/config", HTTP_POST, handlePostConfig);
  server.on("/api/mb/read", HTTP_GET, handleMbRead);
  server.on("/api/mb/write", HTTP_POST, handleMbWrite);
  server.on("/api/mb/findsp", HTTP_POST, handleFindSp);
  server.on("/api/params", HTTP_GET, handleGetParams);
  server.on("/api/params", HTTP_POST, handlePostParam);
  server.on("/api/action", HTTP_POST, handleAction);
  server.onNotFound([] { sendBody(404, "text/plain", (const uint8_t*)"Not found", 9, "404"); });
  server.begin();
}

void webLoop() {
  server.handleClient();
  if (restartAt && (int32_t)(millis() - restartAt) >= 0) ESP.restart();
}
